mapper.select:
SELECT u.id, u.username, u.password, u.real_name AS realName, u.sidx, u.avatar_url AS avatarUrl, u.birth, u.sex, u.email, u.phone, u.role_id AS roleId, u.dept_id AS deptId, r.role_name AS roleName, d.dept_name AS deptName, u.wxapp_uid AS wxappUid, u.wxapp_openid AS wxappOpenid, u.is_disable AS isDisable, u.status, u.remark FROM sys_user u LEFT JOIN sys_user_role ur ON ur.user_id = u.id LEFT JOIN sys_role r ON r.id = ur.role_id LEFT JOIN sys_dept d ON d.id = u.dept_id
AND INSTR(u.username, #{queryForm.username})
AND INSTR(u.real_name, #{queryForm.realName})
AND INSTR(u.phone, #{queryForm.phone})
AND INSTR(u.email, #{queryForm.email})
AND u.dept_id = #{queryForm.deptId}
AND ur.role_id = #{queryForm.roleId}
AND u.sex = #{queryForm.sex}
ORDER BY u.id DESC
